 const reset=(i=slotIndex,isLive=false)=>{setPreviewIndex(i);setLive(isLive);trackedPhase("idle");setSeconds(slots[i].minutes*60);setPages(0)};
 const recordExecution=(record:ExecutionRecord)=>{setSavedCount(saveExecution(record));setExecutionRecords(readExecutionLog())};
 const finish=()=>{const isPrayer=runningActivity?.template==="صلاة",durationSeconds=isPrayer?0:elapsed,minutes=durationSeconds/60,quantity=isPrayer?1:slot.reading?pages:undefined;recordExecution({id:globalThis.crypto?.randomUUID?.(),activityId:runningActivity?.id??actionActivity?.id,activity:slot.activity,minutes,durationSeconds,quantity,targetQuantity:isPrayer?1:slot.reading?5:undefined,quantityUnit:isPrayer?"مرة":slot.reading?"صفحة":undefined,activityKind:isPrayer?"single":slot.reading?"quantity":"time",completedAt:new Date().toISOString(),status:"completed",dueKey:riyadhDay(actualToday)});trackedPhase("done")};
 const startCurrent=()=>{setPages(0);startActivityClock(slot.minutes*60)};
 const startTask=(activity?:PlannedActivity,period?:string,contextDate=actualToday)=>{if(!activity||leavingJourney)return;setLeavingJourney(true);window.setTimeout(()=>{setLeavingJourney(false);setRunningActivity(activity);setNavView("activities");setTab("now");if(activity.unitTracking){const currentDate=riyadhDay(contextDate),currentPeriod=period??slots[windowNow.index]?.period??slots[selectedDay].period;setActiveDhikrDate(currentDate);setActiveDhikrPeriod(currentPeriod);setActiveDhikr(activity);return}if(activity.template==="رياضة"&&activity.exercises?.length){setActiveWorkoutDate(riyadhDay(contextDate));setActiveWorkout(activity);return}startActivityClock((activity.nature==="goal"?(activity.supportingPlan?.expectedMinutes??activity.expectedMinutes):activity.expectedMinutes)*60)},240)};
 const returnToJourney=()=>{setNavView("activities");setActiveWorkout(null);setActiveWorkoutDate(null);setActiveDhikr(null);setActiveDhikrDate(null);setActiveDhikrPeriod(undefined);trackedPhase("idle");setViewMotion("back");window.setTimeout(()=>setViewMotion(null),420)};
 const openJourneyTask=(task:JourneyTask,contextDate=actualToday)=>{if(task.kind==="add"){openActivity(null,"commitment",null,task.period);return}if(task.appointment){openAppointment(task.appointment);return}if(task.task){openTask(task.task);return}if(task.activity)startTask(task.activity,task.period??slots[selectedDay].period,contextDate)};
 const openActivity=(activity:PlannedActivity|null,nature:"goal"|"commitment"=activity?.nature??"commitment",preset:ActivityPreset|null=null,period?:string)=>{setCreationNature(nature);setQuickTemplate(preset);setActivityPeriod(period);setEditingActivity(activity);window.setTimeout(()=>$("add-sheet")?.showModal(),0)};
 const openDhikrSettings=(activity:PlannedActivity)=>{setEditingDhikr(activity);window.setTimeout(()=>$("dhikr-settings")?.showModal(),0)};
 const openQuickAdd=(preset:ActivityPreset)=>{ $("quick-add")?.close();openActivity(null,preset.nature,preset)};
 const showQuickAdd=()=>{if(navView==="tasks"){window.setTimeout(()=>$('calendar-type-picker')?.showModal(),0);return}setQuickAddScope(navView==="activities"?"activities":"general");window.setTimeout(()=>$('quick-add')?.showModal(),0)};
 const openUnifiedTask=()=>{$("quick-add")?.close();window.setTimeout(()=>$('calendar-type-picker')?.showModal(),0)};
 const saveActivity=(activity:PlannedActivity)=>{if(editingActivity){setPlan(updatePlan(activity));return}if(activity.nature==="goal"&&activity.supportingPlan){const commitmentId=`commitment-${activity.id}`;const goal={...activity,linkedCommitmentId:commitmentId,supportingPlan:{...activity.supportingPlan,enabled:false}};const commitment:PlannedActivity={id:commitmentId,nature:"commitment",parentGoalId:activity.id,name:activity.supportingPlan.actionName,template:activity.template,period:activity.supportingPlan.period,goal:`يقود إلى ${activity.name}`,expectedMinutes:activity.supportingPlan.expectedMinutes,schedule:activity.supportingPlan.schedule,quantity:activity.quantity,unit:activity.unit,measurements:activity.measurements,exercises:activity.exercises,reminder:{mode:"station",value:activity.supportingPlan.period}};savePlan(goal);setPlan(savePlan(commitment));return}setPlan(savePlan(activity))};
 const saveGaugeStyle=(style:GaugeStyle)=>{if(!activeDhikr?.unitTracking)return;const updated={...activeDhikr,unitTracking:{...activeDhikr.unitTracking,gaugeStyle:style}};setPlan(updatePlan(updated));setActiveDhikr(updated)};
 const openTask=(item:TaskItem|null,urgent=false)=>{setEditingTask(item);setNewTaskUrgent(item?.urgent??urgent);window.setTimeout(()=>$("task-sheet")?.showModal(),0)};
 const openRecordEditor=(task:TaskItem|null,appointment:Appointment|null,kind?:CalendarRecordKind)=>{setRecordEditorTask(task);setRecordEditorAppointment(appointment);setRecordEditorVersion(value=>value+1);if(kind&&!task&&!appointment)setCalendarAddKind(kind);window.setTimeout(()=>$('record-entry-sheet')?.showModal(),0)};
 const openCategoryEditor=()=>window.setTimeout(()=>$('calendar-category-sheet')?.showModal(),0);
 const saveCategory=(name:string)=>{const category={id:`category-${globalThis.crypto?.randomUUID?.()??Date.now()}`,name,createdAt:new Date().toISOString()};setCalendarCategories(saveCalendarCategory(category))};
 const openAppointment=(item:Appointment|null)=>{setEditingAppointment(item);if(item){setCalendarAddKind(item.kind??"appointment");setCalendarFormKey(value=>value+1);window.setTimeout(()=>$("appointment-sheet")?.showModal(),0)}else window.setTimeout(()=>$("calendar-type-picker")?.showModal(),0)};
 const openCalendarForm=(kind:CalendarRecordKind)=>{setCalendarAddKind(kind);setEditingAppointment(null);setCalendarFormKey(value=>value+1);$("calendar-type-picker")?.close();window.setTimeout(()=>$("appointment-sheet")?.showModal(),0)};
