 const buckets=Array.from({length:bucketCount},()=>0);visible.forEach(record=>{const age=Math.max(0,now-new Date(record.completedAt).getTime()),index=Math.max(0,Math.min(bucketCount-1,bucketCount-1-Math.floor(age/(days*86400000/bucketCount))));buckets[index]+=record.minutes});
 const cumulative=buckets.reduce<number[]>((values,value,index)=>[...values,value+(values[index-1]??0)],[]),plannedCumulative=Array.from({length:bucketCount},(_,index)=>plannedMinutes*((index+1)/bucketCount));
 const maxValue=Math.max(1,plannedMinutes,actualMinutes),point=(value:number,index:number)=>`${20+(index*(280/Math.max(1,bucketCount-1)))},${145-(value/maxValue)*112}`;
